import { forwardRef, isValidElement, useImperativeHandle, useMemo, useRef, type ComponentProps, type ReactNode } from "react";
import { AbsoluteFill, Img, Interactive, Sequence, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

type BackdropFill =
  | { type: "color"; value: string }
  | { type: "gradient"; value: string }
  | { type: "image"; src: string; fit?: "cover" | "contain" };

interface BackdropProps {
  fill?: BackdropFill | ReactNode;
  padding?: number;
  radius?: number;
  shadow?: string;
  children?: ReactNode;
  className?: string;
}

const DEFAULT_FILL: BackdropFill = { type: "color", value: "#0a0a0a" };

function FillLayer({ fill }: { fill: BackdropFill }) {
  if (fill.type === "image") {
    return (
      <AbsoluteFill>
        <Img
          src={fill.src}
          style={{
            width: "100%",
            height: "100%",
            objectFit: fill.fit ?? "cover",
          }}
        />
      </AbsoluteFill>
    );
  }

  return <AbsoluteFill style={{ background: fill.value }} />;
}

function BackdropBase({
  fill,
  padding = 4,
  radius = 1,
  shadow = "0 20px 60px rgba(0,0,0,0.4)",
  children,
  className,
}: BackdropProps) {
  const { width } = useSceneConfig();

  const paddingPx = (padding / 100) * width;
  const radiusPx = (radius / 100) * width;

  const fillLayer = isValidElement(fill) ? (
    <AbsoluteFill>{fill}</AbsoluteFill>
  ) : (
    <FillLayer fill={(fill as BackdropFill | undefined) ?? DEFAULT_FILL} />
  );

  return (
    <AbsoluteFill className={className}>
      {fillLayer}
      {children != null && (
        <div
          style={{
            position: "absolute",
            inset: paddingPx,
            overflow: "hidden",
            borderRadius: radiusPx,
            display: "flex",
            ...(shadow === "" ? {} : { boxShadow: shadow }),
          }}
        >
          <div style={{ width: "100%", height: "100%" }}>{children}</div>
        </div>
      )}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  fillType: {
    type: "enum",
    default: "gradient",
    variants: {
      color: {},
      gradient: {},
      image: {},
    },
    description: "Fill type",
  },
  color: {
    type: "color",
    default: "#6366f1",
    description: "Color",
  },
  gradient: {
    type: "text-content",
    default: "linear-gradient(135deg, #6366f1 0%, #a855f7 100%)",
    description: "Gradient (CSS)",
  },
  image: {
    type: "text-content",
    default: "/hero.png",
    description: "Image URL",
  },
  padding: {
    type: "number",
    min: 0,
    max: 12,
    step: 0.5,
    default: 4,
    description: "Padding",
    hiddenFromList: false,
  },
  radius: {
    type: "number",
    min: 0,
    max: 4,
    step: 0.25,
    default: 1,
    description: "Radius",
    hiddenFromList: false,
  },
  shadow: {
    type: "text-content",
    default: "0 20px 60px rgba(0,0,0,0.4)",
    description: "Shadow",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["fillType","color","gradient","image","padding","radius","shadow"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  fillType: "gradient",
  color: "#6366f1",
  gradient: "linear-gradient(135deg, #6366f1 0%, #a855f7 100%)",
  image: "/hero.png",
  padding: 4,
  radius: 1,
  shadow: "0 20px 60px rgba(0,0,0,0.4)",
};

type BackdropElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof BackdropBase>;

const BackdropInner = forwardRef<
  HTMLDivElement,
  BackdropElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<Backdrop>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <BackdropBase
          {...(componentProps as unknown as ComponentProps<typeof BackdropBase>)}
        />
      </div>
    </Sequence>
  );
});

export const Backdrop = Interactive.withSchema({
  Component: BackdropInner,
  componentName: "<Backdrop>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
